def find_first_occurrence(arr, target):
    def binary_search_leftmost(arr, target, low, high):
        """Helper function to find the index of the leftmost occurrence of target."""
        result = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == target:
                result = mid  # potential target found, move left to ensure leftmost
                high = mid - 1
            elif arr[mid] < target:
                low = mid + 1
            else:
